import sys
import requests
import xml.etree.ElementTree as ET
import re

def parse_config(config_path):
    config = {}
    with open(config_path, 'r') as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            key, value = line.split('=', 1)
            config[key.strip()] = value.strip()
    return config

def evaluate_threshold(threshold_str):
    try:
        return eval(threshold_str)
    except:
        return 0.0

def fetch_and_parse_xml(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
        root = ET.fromstring(response.content)
        prices = []
        for elem in root.findall('.//price'):
            try:
                prices.append(float(elem.text))
            except ValueError:
                continue
        return sum(prices)
    except:
        return 0.0

def main():
    if len(sys.argv) != 2:
        print("Usage: python check_stock.py <config_file>")
        sys.exit(1)

    config = parse_config(sys.argv[1])
    feed_url = config.get('feed_url')
    threshold_str = config.get('threshold')

    if not feed_url or not threshold_str:
        print("Missing required configuration keys")
        sys.exit(1)

    total_price = fetch_and_parse_xml(feed_url)
    threshold = evaluate_threshold(threshold_str)

    if total_price > threshold:
        print("OK")
    else:
        print("LOW")

if __name__ == "__main__":
    main()

