import sys
import requests
import xml.etree.ElementTree as ET

def read_config(file_path):
    config = {}
    with open(file_path, 'r') as f:
        for line in f:
            line = line.strip()
            if line and not line.startswith('#'):
                key, value = line.split('=', 1)
                config[key.strip()] = value.strip()
    return config

def fetch_prices(feed_url):
    response = requests.get(feed_url)
    response.raise_for_status()
    return ET.fromstring(response.content)

def sum_prices(xml_root):
    prices = [float(price.text) for price in xml_root.findall('.//price')]
    return sum(prices)

def evaluate_threshold(threshold):
    return eval(threshold)

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print('Usage: python check_stock.py <config_file_path>')
        sys.exit(1)

    config_file_path = sys.argv[1]
    config = read_config(config_file_path)
    feed_url = config.get('feed_url')
    threshold = config.get('threshold')

    if not feed_url or not threshold:
        print('Missing feed_url or threshold in configuration.')
        sys.exit(1)

    xml_root = fetch_prices(feed_url)
    total_price = sum_prices(xml_root)
    evaluated_threshold = evaluate_threshold(threshold)

    if total_price > evaluated_threshold:
        print('OK')
    else:
        print('LOW')
